class NextScrollReading{static instances=[];constructor(element){Object.assign(this,{element,start:element.getAttribute("data-start"),duration:parseFloat(element.getAttribute("data-duration")),end:element.getAttribute("data-end"),type:element.getAttribute("data-type"),readingType:element.getAttribute("data-reading-type")||"fill",fadeOpacity:parseFloat(element.getAttribute("data-fade-opacity")),scroller:element.getAttribute("data-scroller"),splitTexts:[],scrollTriggers:[],windowWidth:window.innerWidth,lines:[],words:[],chars:[]});if(!Number.isFinite(this.fadeOpacity)){this.fadeOpacity=0.2}
this.initialize()}
initialize(){this.updateContent();this.createSplitText();this.createAnimations();this.setupResizeListener()}
updateContent(){const content=this.element.getAttribute('data-content');if(content){this.element.innerHTML=content}}
createSplitText(){this.splitTexts.forEach(split=>split.revert());this.splitTexts=[];const splitText=new SplitText(this.element,{type:"lines, words, chars",linesClass:"line",wordsClass:"word",charsClass:"char"});this.lines=splitText.lines;this.words=splitText.words;this.chars=splitText.chars;this.splitTexts.push(splitText);const targets=this.getTargetElements();if(this.readingType==="fade"){targets.forEach(target=>gsap.set(target,{opacity:this.fadeOpacity}))}else{this.addMasks(targets)}}
getTargetElements(){switch(this.type){case "lines":return this.lines;case "words":return this.words;case "chars":return this.chars;default:return this.words}}
addMasks(elements){elements.forEach(element=>{const mask=document.createElement("div");mask.className="dan-scroll-reading__line-mask";element.appendChild(mask)})}
createAnimations(){const elements=this.getTargetElements();if(this.readingType==="fade"){const fadeTween=gsap.to(elements,{opacity:1,stagger:0.1,scrollTrigger:{trigger:this.element,start:this.start,end:this.end,scrub:this.duration,scroller:this.scroller}});if(fadeTween.scrollTrigger){this.scrollTriggers.push(fadeTween.scrollTrigger)}
return}
elements.forEach(element=>{const timeline=gsap.timeline({scrollTrigger:{trigger:element,start:this.start,end:this.end,scrub:this.duration,scroller:this.scroller}}).to(element.querySelector(".dan-scroll-reading__line-mask"),{width:"0%",duration:1});if(timeline.scrollTrigger){this.scrollTriggers.push(timeline.scrollTrigger)}})}
clearScrollTriggers(){this.scrollTriggers.forEach(trigger=>trigger.kill());this.scrollTriggers=[]}
setupResizeListener(){this.resizeHandler=()=>{if(this.windowWidth!==window.innerWidth){this.windowWidth=window.innerWidth;this.refresh()}};window.addEventListener("resize",this.resizeHandler)}
refresh(){this.clearScrollTriggers();this.splitTexts.forEach(split=>split.revert());this.splitTexts=[];this.updateContent();this.createSplitText();this.createAnimations()}
destroy(){window.removeEventListener("resize",this.resizeHandler);this.clearScrollTriggers();this.splitTexts.forEach(split=>split.revert());this.updateContent()}
static destroyAll(){NextScrollReading.instances.forEach(instance=>instance.destroy());NextScrollReading.instances=[]}}
const dancepad_scroll_reading=()=>{gsap.registerPlugin(ScrollTrigger);NextScrollReading.destroyAll();setTimeout(()=>{document.querySelectorAll(".dan-scroll-reading__element").forEach(element=>{element.removeAttribute('data-flickering');NextScrollReading.instances.push(new NextScrollReading(element))})},50)}